   1→import { useState, useCallback, useMemo, useEffect } from "react";
   2→import type {
   3→  ActionFunctionArgs,
   4→  HeadersFunction,
   5→  LoaderFunctionArgs,
   6→} from "react-router";
   7→import { useFetcher, useLoaderData, useNavigate, useRouteError } from "react-router";
   8→import { useAppBridge } from "@shopify/app-bridge-react";
   9→import { authenticate } from "../shopify.server";
  10→import { boundary } from "@shopify/shopify-app-react-router/server";
  11→import db from "../db.server";
  12→import {
  13→  Page,
  14→  Layout,
  15→  Card,
  16→  BlockStack,
  17→  InlineStack,
  18→  Text,
  19→  Button,
  20→  TextField,
  21→  Select,
  22→  Modal,
  23→  EmptyState,
  24→  Divider,
  25→  Box,
  26→  Badge,
  27→  Tabs,
  28→  InlineGrid,
  29→  Banner,
  30→} from "@shopify/polaris";
  31→import { PlusIcon, DeleteIcon, ChevronUpIcon, EditIcon } from "@shopify/polaris-icons";
  32→
  33→const PAGE_SIZE = 10;
  34→const ADMIN_SHOP = "zip-code-checker.myshopify.com";
  35→const MAX_REQUESTS_PER_SHOP = 20;
  36→const MAX_DESCRIPTION_LENGTH = 2000;
  37→
  38→// ---------------------------------------------------------------------------
  39→// Types
  40→// ---------------------------------------------------------------------------
  41→
  42→type FeatureRequestRecord = {
  43→  id: string;
  44→  title: string;
  45→  description: string;
  46→  category: string;
  47→  status: string;
  48→  shop: string;
  49→  votesCount: number;
  50→  createdAt: string | Date;
  51→  updatedAt: string | Date;
  52→};
  53→
  54→type VoteResult = {
  55→  success: true;
  56→  intent: "vote";
  57→  featureId: string;
  58→  newCount: number;
  59→  voted: boolean;
  60→};
  61→type SubmitResult = { success: true; intent: "submit" };
  62→type DeleteResult = { success: true; intent: "delete" };
  63→type StatusResult = { success: true; intent: "update-status" };
  64→type EditResult = { success: true; intent: "edit" };
  65→type ErrorResult = { error: string };
  66→
  67→type ActionResult =
  68→  | VoteResult
  69→  | SubmitResult
  70→  | DeleteResult
  71→  | StatusResult
  72→  | EditResult
  73→  | ErrorResult;
  74→
  75→// ---------------------------------------------------------------------------
  76→// Constants
  77→// ---------------------------------------------------------------------------
  78→
  79→const VALID_CATEGORIES = new Set([
  80→  "General",
  81→  "UI & Design",
  82→  "Data & Export",
  83→  "API & Integration",
  84→  "Performance",
  85→  "Billing",
  86→]);
  87→
  88→const VALID_STATUSES = new Set([
  89→  "under_review",
  90→  "planned",
  91→  "in_progress",
  92→  "done",
  93→  "shipped",
  94→]);
  95→
  96→const STATUS_LABELS: Record<string, string> = {
  97→  under_review: "Under Review",
  98→  planned: "Planned",
  99→  in_progress: "In Progress",
 100→  done: "Done",
 101→  shipped: "Shipped",
 102→};
 103→
 104→type BadgeTone =
 105→  | "attention"
 106→  | "info"
 107→  | "warning"
 108→  | "success"
 109→  | "critical"
 110→  | undefined;
 111→
 112→const STATUS_TONES: Record<string, BadgeTone> = {
 113→  under_review: "attention",
 114→  planned: "info",
 115→  in_progress: "warning",
 116→  done: "success",
 117→  shipped: "success",
 118→};
 119→
 120→const CATEGORY_OPTIONS = [
 121→  { label: "General", value: "General" },
 122→  { label: "UI & Design", value: "UI & Design" },
 123→  { label: "Data & Export", value: "Data & Export" },
 124→  { label: "API & Integration", value: "API & Integration" },
 125→  { label: "Performance", value: "Performance" },
 126→  { label: "Billing", value: "Billing" },
 127→];
 128→
 129→const STATUS_OPTIONS = [
 130→  { label: "Under Review", value: "under_review" },
 131→  { label: "Planned", value: "planned" },
 132→  { label: "In Progress", value: "in_progress" },
 133→  { label: "Done", value: "done" },
 134→  { label: "Shipped", value: "shipped" },
 135→];
 136→
 137→const TAB_FILTERS = [
 138→  "all",
 139→  "under_review",
 140→  "planned",
 141→  "in_progress",
 142→  "done",
 143→] as const;
 144→type TabFilter = (typeof TAB_FILTERS)[number];
 145→
 146→const SORT_OPTIONS = [
 147→  { label: "Most Voted", value: "votes" },
 148→  { label: "Newest", value: "newest" },
 149→  { label: "Oldest", value: "oldest" },
 150→];
 151→
 152→function formatDate(d: string | Date): string {
 153→  return new Date(d).toLocaleDateString("en-US", {
 154→    month: "short",
 155→    day: "numeric",
 156→    year: "numeric",
 157→  });
 158→}
 159→
 160→function truncateText(text: string, maxChars: number): string {
 161→  if (text.length <= maxChars) return text;
 162→  return text.slice(0, maxChars).trimEnd() + "\u2026";
 163→}
 164→
 165→// ---------------------------------------------------------------------------
 166→// Loader
 167→// ---------------------------------------------------------------------------
 168→
 169→export const loader = async ({ request }: LoaderFunctionArgs) => {
 170→  const { session } = await authenticate.admin(request);
 171→  const shop = session.shop;
 172→
 173→  const [features, myVotes] = await Promise.all([
 174→    db.featureRequest.findMany({
 175→      orderBy: { votesCount: "desc" },
 176→      take: 500,
 177→    }),
 178→    db.featureVote.findMany({
 179→      where: { shop },
 180→      select: { featureRequestId: true },
 181→    }),
 182→  ]);
 183→
 184→  const votedIds = myVotes.map((v) => v.featureRequestId);
 185→
 186→  const stats = {
 187→    total: features.length,
 188→    under_review: features.filter((f) => f.status === "under_review").length,
 189→    planned: features.filter((f) => f.status === "planned").length,
 190→    in_progress: features.filter((f) => f.status === "in_progress").length,
 191→    done: features.filter(
 192→      (f) => f.status === "done" || f.status === "shipped",
 193→    ).length,
 194→  };
 195→
 196→  const isAdmin = shop === ADMIN_SHOP;
 197→
 198→  return { features, votedIds, shop, stats, isAdmin };
 199→};
 200→
 201→// ---------------------------------------------------------------------------
 202→// Action
 203→// ---------------------------------------------------------------------------
 204→
 205→export const action = async ({
 206→  request,
 207→}: ActionFunctionArgs): Promise<ActionResult> => {
 208→  const { session } = await authenticate.admin(request);
 209→  const shop = session.shop;
 210→  const isAdmin = shop === ADMIN_SHOP;
 211→  const formData = await request.formData();
 212→  const intent = String(formData.get("intent") ?? "");
 213→
 214→  try {
 215→    switch (intent) {
 216→      case "submit": {
 217→        const title = String(formData.get("title") ?? "").trim();
 218→        const description = String(formData.get("description") ?? "").trim();
 219→        const rawCategory = String(formData.get("category") ?? "General").trim();
 220→        const category = VALID_CATEGORIES.has(rawCategory) ? rawCategory : "General";
 221→
 222→        if (!title || !description) {
 223→          return { error: "Title and description are required." };
 224→        }
 225→        if (title.length > 150) {
 226→          return { error: "Title must be 150 characters or fewer." };
 227→        }
 228→        if (description.length > MAX_DESCRIPTION_LENGTH) {
 229→          return { error: `Description must be ${MAX_DESCRIPTION_LENGTH} characters or fewer.` };
 230→        }
 231→
 232→        // Per-shop submission limit
 233→        const existingCount = await db.featureRequest.count({ where: { shop } });
 234→        if (existingCount >= MAX_REQUESTS_PER_SHOP) {
 235→          return { error: `You can submit up to ${MAX_REQUESTS_PER_SHOP} feature requests. Delete an existing one to submit a new one.` };
 236→        }
 237→
 238→        await db.featureRequest.create({
 239→          data: { title, description, category, shop },
 240→        });
 241→
 242→        return { success: true, intent: "submit" };
 243→      }
 244→
 245→      case "vote": {
 246→        const featureId = String(formData.get("featureId") ?? "").trim();
 247→        if (!featureId) return { error: "Feature ID is required." };
 248→
 249→        const feature = await db.featureRequest.findUnique({
 250→          where: { id: featureId },
 251→        });
 252→        if (!feature) return { error: "Feature request not found." };
 253→
 254→        const existing = await db.featureVote.findUnique({
 255→          where: {
 256→            featureRequestId_shop: { featureRequestId: featureId, shop },
 257→          },
 258→        });
 259→
 260→        let voted: boolean;
 261→
 262→        if (existing) {
 263→          await db.featureVote.delete({ where: { id: existing.id } });
 264→          // Atomic decrement
 265→          const updated = await db.featureRequest.update({
 266→            where: { id: featureId },
 267→            data: { votesCount: { decrement: 1 } },
 268→          });
 269→          // Ensure count doesn't go below 0
 270→          if (updated.votesCount < 0) {
 271→            await db.featureRequest.update({
 272→              where: { id: featureId },
 273→              data: { votesCount: 0 },
 274→            });
 275→          }
 276→          voted = false;
 277→          const finalCount = Math.max(0, updated.votesCount);
 278→          return { success: true, intent: "vote", featureId, newCount: finalCount, voted };
 279→        } else {
 280→          await db.featureVote.create({
 281→            data: { featureRequestId: featureId, shop },
 282→          });
 283→          // Atomic increment
 284→          const updated = await db.featureRequest.update({
 285→            where: { id: featureId },
 286→            data: { votesCount: { increment: 1 } },
 287→          });
 288→          voted = true;
 289→          return { success: true, intent: "vote", featureId, newCount: updated.votesCount, voted };
 290→        }
 291→      }
 292→
 293→      case "delete": {
 294→        const deleteId = String(formData.get("id") ?? "").trim();
 295→        if (!deleteId) return { error: "Feature ID is required." };
 296→
 297→        const toDelete = await db.featureRequest.findUnique({
 298→          where: { id: deleteId },
 299→        });
 300→        if (!toDelete) return { error: "Feature request not found." };
 301→
 302→        // Admin can delete any, regular users only their own
 303→        if (!isAdmin && toDelete.shop !== shop) {
 304→          return { error: "You can only delete your own feature requests." };
 305→        }
 306→
 307→        await db.featureRequest.delete({ where: { id: deleteId } });
 308→        return { success: true, intent: "delete" };
 309→      }
 310→
 311→      case "edit": {
 312→        const editId = String(formData.get("id") ?? "").trim();
 313→        const editTitle = String(formData.get("title") ?? "").trim();
 314→        const editDescription = String(formData.get("description") ?? "").trim();
 315→        const rawEditCategory = String(formData.get("category") ?? "General").trim();
 316→        const editCategory = VALID_CATEGORIES.has(rawEditCategory) ? rawEditCategory : "General";
 317→
 318→        if (!editId) return { error: "Feature ID is required." };
 319→        if (!editTitle || !editDescription) {
 320→          return { error: "Title and description are required." };
 321→        }
 322→        if (editTitle.length > 150) {
 323→          return { error: "Title must be 150 characters or fewer." };
 324→        }
 325→        if (editDescription.length > MAX_DESCRIPTION_LENGTH) {
 326→          return { error: `Description must be ${MAX_DESCRIPTION_LENGTH} characters or fewer.` };
 327→        }
 328→
 329→        const toEdit = await db.featureRequest.findUnique({ where: { id: editId } });
 330→        if (!toEdit) return { error: "Feature request not found." };
 331→
 332→        if (!isAdmin && toEdit.shop !== shop) {
 333→          return { error: "You can only edit your own feature requests." };
 334→        }
 335→
 336→        await db.featureRequest.update({
 337→          where: { id: editId },
 338→          data: { title: editTitle, description: editDescription, category: editCategory },
 339→        });
 340→
 341→        return { success: true, intent: "edit" };
 342→      }
 343→
 344→      case "update-status": {
 345→        if (!isAdmin) {
 346→          return { error: "Only the app admin can change request statuses." };
 347→        }
 348→
 349→        const statusId = String(formData.get("id") ?? "").trim();
 350→        const newStatus = String(formData.get("status") ?? "").trim();
 351→
 352→        if (!statusId) return { error: "Feature ID is required." };
 353→        if (!VALID_STATUSES.has(newStatus)) {
 354→          return { error: "Invalid status value." };
 355→        }
 356→
 357→        const toUpdate = await db.featureRequest.findUnique({
 358→          where: { id: statusId },
 359→        });
 360→        if (!toUpdate) return { error: "Feature request not found." };
 361→
 362→        await db.featureRequest.update({
 363→          where: { id: statusId },
 364→          data: { status: newStatus },
 365→        });
 366→
 367→        return { success: true, intent: "update-status" };
 368→      }
 369→
 370→      default:
 371→        return { error: "Unknown action." };
 372→    }
 373→  } catch (err) {
 374→    const message =
 375→      err instanceof Error ? err.message : "An unexpected error occurred.";
 376→    return { error: message };
 377→  }
 378→};
 379→
 380→// ---------------------------------------------------------------------------
 381→// Component
 382→// ---------------------------------------------------------------------------
 383→
 384→export default function FeatureRequestsPage() {
 385→  const {
 386→    features: rawFeatures,
 387→    votedIds: initialVotedIds,
 388→    shop,
 389→    stats,
 390→    isAdmin,
 391→  } = useLoaderData<typeof loader>();
 392→
 393→  // Separate fetchers for independent actions (Fix #6)
 394→  const voteFetcher = useFetcher<typeof action>();
 395→  const deleteFetcher = useFetcher<typeof action>();
 396→  const submitFetcher = useFetcher<typeof action>();
 397→  const statusFetcher = useFetcher<typeof action>();
 398→  const editFetcher = useFetcher<typeof action>();
 399→
 400→  const shopify = useAppBridge();
 401→  const navigate = useNavigate();
 402→
 403→  // ------------------------------------------------------------------
 404→  // Local state — optimistic votes
 405→  // ------------------------------------------------------------------
 406→  const [optimisticVotes, setOptimisticVotes] = useState<
 407→    Map<string, { count: number; voted: boolean }>
 408→  >(() => new Map());
 409→  const [votedIds, setVotedIds] = useState<Set<string>>(
 410→    () => new Set(initialVotedIds),
 411→  );
 412→
 413→  // Per-card loading indicators
 414→  const [pendingVoteId, setPendingVoteId] = useState<string | null>(null);
 415→  const [pendingDeleteId, setPendingDeleteId] = useState<string | null>(null);
 416→
 417→  // ------------------------------------------------------------------
 418→  // UI state
 419→  // ------------------------------------------------------------------
 420→  const [selectedTab, setSelectedTab] = useState(0);
 421→  const [sortValue, setSortValue] = useState("votes");
 422→  const [currentPage, setCurrentPage] = useState(1);
 423→  const [modalOpen, setModalOpen] = useState(false);
 424→  const [expandedIds, setExpandedIds] = useState<Set<string>>(new Set());
 425→  const [modalError, setModalError] = useState<string | null>(null);
 426→
 427→  // Form state
 428→  const [newTitle, setNewTitle] = useState("");
 429→  const [newDescription, setNewDescription] = useState("");
 430→  const [newCategory, setNewCategory] = useState("General");
 431→
 432→  // Edit modal state
 433→  const [editModalOpen, setEditModalOpen] = useState(false);
 434→  const [editId, setEditId] = useState("");
 435→  const [editTitle, setEditTitle] = useState("");
 436→  const [editDescription, setEditDescription] = useState("");
 437→  const [editCategory, setEditCategory] = useState("General");
 438→  const [editModalError, setEditModalError] = useState<string | null>(null);
 439→
 440→  // ------------------------------------------------------------------
 441→  // Resolve optimistic state into features list
 442→  // ------------------------------------------------------------------
 443→  const features = useMemo<FeatureRequestRecord[]>(() => {
 444→    return (rawFeatures as FeatureRequestRecord[]).map((f) => {
 445→      const opt = optimisticVotes.get(f.id);
 446→      if (opt) return { ...f, votesCount: opt.count };
 447→      return f;
 448→    });
 449→  }, [rawFeatures, optimisticVotes]);
 450→
 451→  // ------------------------------------------------------------------
 452→  // Handle vote fetcher responses
 453→  // ------------------------------------------------------------------
 454→  useEffect(() => {
 455→    if (voteFetcher.state !== "idle" || !voteFetcher.data) return;
 456→    const data = voteFetcher.data;
 457→
 458→    if ("error" in data) {
 459→      shopify.toast.show(data.error, { isError: true });
 460→      setPendingVoteId(null);
 461→      return;
 462→    }
 463→
 464→    if ("success" in data && data.success && data.intent === "vote") {
 465→      const voteData = data as VoteResult;
 466→      setOptimisticVotes((prev) => {
 467→        const next = new Map(prev);
 468→        next.set(voteData.featureId, {
 469→          count: voteData.newCount,
 470→          voted: voteData.voted,
 471→        });
 472→        return next;
 473→      });
 474→      setVotedIds((prev) => {
 475→        const next = new Set(prev);
 476→        if (voteData.voted) next.add(voteData.featureId);
 477→        else next.delete(voteData.featureId);
 478→        return next;
 479→      });
 480→      setPendingVoteId(null);
 481→    }
 482→  }, [voteFetcher.state, voteFetcher.data, shopify]);
 483→
 484→  // ------------------------------------------------------------------
 485→  // Handle delete fetcher responses
 486→  // ------------------------------------------------------------------
 487→  useEffect(() => {
 488→    if (deleteFetcher.state !== "idle" || !deleteFetcher.data) return;
 489→    const data = deleteFetcher.data;
 490→
 491→    if ("error" in data) {
 492→      shopify.toast.show(data.error, { isError: true });
 493→      setPendingDeleteId(null);
 494→      return;
 495→    }
 496→
 497→    if ("success" in data && data.success && data.intent === "delete") {
 498→      shopify.toast.show("Feature request deleted.");
 499→      setPendingDeleteId(null);
 500→    }
 501→  }, [deleteFetcher.state, deleteFetcher.data, shopify]);
 502→
 503→  // ------------------------------------------------------------------
 504→  // Handle submit fetcher responses
 505→  // ------------------------------------------------------------------
 506→  useEffect(() => {
 507→    if (submitFetcher.state !== "idle" || !submitFetcher.data) return;
 508→    const data = submitFetcher.data;
 509→
 510→    if ("error" in data) {
 511→      setModalError(data.error);
 512→      return;
 513→    }
 514→
 515→    if ("success" in data && data.success && data.intent === "submit") {
 516→      shopify.toast.show("Feature request submitted! Thank you.");
 517→      setModalOpen(false);
 518→      setNewTitle("");
 519→      setNewDescription("");
 520→      setNewCategory("General");
 521→      setModalError(null);
 522→      // Bring the new request into view: switch to All tab, sort by Newest, page 1
 523→      setSelectedTab(0);
 524→      setSortValue("newest");
 525→      setCurrentPage(1);
 526→    }
 527→  }, [submitFetcher.state, submitFetcher.data, shopify]);
 528→
 529→  // ------------------------------------------------------------------
 530→  // Handle status fetcher responses
 531→  // ------------------------------------------------------------------
 532→  useEffect(() => {
 533→    if (statusFetcher.state !== "idle" || !statusFetcher.data) return;
 534→    const data = statusFetcher.data;
 535→
 536→    if ("error" in data) {
 537→      shopify.toast.show(data.error, { isError: true });
 538→      return;
 539→    }
 540→
 541→    if ("success" in data && data.success && data.intent === "update-status") {
 542→      shopify.toast.show("Status updated.");
 543→    }
 544→  }, [statusFetcher.state, statusFetcher.data, shopify]);
 545→
 546→  // ------------------------------------------------------------------
 547→  // Handle edit fetcher responses
 548→  // ------------------------------------------------------------------
 549→  useEffect(() => {
 550→    if (editFetcher.state !== "idle" || !editFetcher.data) return;
 551→    const data = editFetcher.data;
 552→
 553→    if ("error" in data) {
 554→      setEditModalError(data.error);
 555→      return;
 556→    }
 557→
 558→    if ("success" in data && data.success && data.intent === "edit") {
 559→      shopify.toast.show("Feature request updated.");
 560→      setEditModalOpen(false);
 561→      setEditId("");
 562→      setEditTitle("");
 563→      setEditDescription("");
 564→      setEditCategory("General");
 565→      setEditModalError(null);
 566→    }
 567→  }, [editFetcher.state, editFetcher.data, shopify]);
 568→
 569→  // ------------------------------------------------------------------
 570→  // Filter + sort
 571→  // ------------------------------------------------------------------
 572→  const tabFilter: TabFilter = TAB_FILTERS[selectedTab] ?? "all";
 573→
 574→  const filteredFeatures = useMemo(() => {
 575→    let list = features;
 576→
 577→    if (tabFilter !== "all") {
 578→      if (tabFilter === "done") {
 579→        list = list.filter(
 580→          (f) => f.status === "done" || f.status === "shipped",
 581→        );
 582→      } else {
 583→        list = list.filter((f) => f.status === tabFilter);
 584→      }
 585→    }
 586→
 587→    return [...list].sort((a, b) => {
 588→      if (sortValue === "votes") return b.votesCount - a.votesCount;
 589→      if (sortValue === "newest")
 590→        return (
 591→          new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
 592→        );
 593→      if (sortValue === "oldest")
 594→        return (
 595→          new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime()
 596→        );
 597→      return 0;
 598→    });
 599→  }, [features, tabFilter, sortValue]);
 600→
 601→  const totalPages = Math.max(
 602→    1,
 603→    Math.ceil(filteredFeatures.length / PAGE_SIZE),
 604→  );
 605→  const paginatedFeatures = useMemo(() => {
 606→    const start = (currentPage - 1) * PAGE_SIZE;
 607→    return filteredFeatures.slice(start, start + PAGE_SIZE);
 608→  }, [filteredFeatures, currentPage]);
 609→
 610→  // ------------------------------------------------------------------
 611→  // Handlers
 612→  // ------------------------------------------------------------------
 613→  const handleTabChange = useCallback((tabIndex: number) => {
 614→    setSelectedTab(tabIndex);
 615→    setCurrentPage(1);
 616→  }, []);
 617→
 618→  const handleSortChange = useCallback((val: string) => {
 619→    setSortValue(val);
 620→    setCurrentPage(1);
 621→  }, []);
 622→
 623→  const handleVote = useCallback(
 624→    (featureId: string) => {
 625→      const feature = features.find((f) => f.id === featureId);
 626→      if (!feature) return;
 627→
 628→      const currentlyVoted = votedIds.has(featureId);
 629→      const currentCount =
 630→        optimisticVotes.get(featureId)?.count ?? feature.votesCount;
 631→
 632→      // Optimistic update
 633→      setOptimisticVotes((prev) => {
 634→        const next = new Map(prev);
 635→        next.set(featureId, {
 636→          count: currentlyVoted
 637→            ? Math.max(0, currentCount - 1)
 638→            : currentCount + 1,
 639→          voted: !currentlyVoted,
 640→        });
 641→        return next;
 642→      });
 643→      setVotedIds((prev) => {
 644→        const next = new Set(prev);
 645→        if (currentlyVoted) next.delete(featureId);
 646→        else next.add(featureId);
 647→        return next;
 648→      });
 649→
 650→      setPendingVoteId(featureId);
 651→
 652→      const fd = new FormData();
 653→      fd.set("intent", "vote");
 654→      fd.set("featureId", featureId);
 655→      voteFetcher.submit(fd, { method: "POST" });
 656→    },
 657→    [features, votedIds, optimisticVotes, voteFetcher],
 658→  );
 659→
 660→  const handleDelete = useCallback(
 661→    (id: string) => {
 662→      setPendingDeleteId(id);
 663→
 664→      const fd = new FormData();
 665→      fd.set("intent", "delete");
